<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= esc($formTitle) ?> · UIU Recruitment Portal Admin</title><?php $adminSection='exams'; ?><?= $this->include('admin/_styles') ?></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title"><?= esc($formTitle) ?></div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><div class="admin-heading"><div><h1><?= esc($formTitle) ?></h1><p>Configure the assessment before adding its questions.</p></div><a href="<?= site_url('admin/exams') ?>" style="color:#168fd4;font-size:13px">← Back to exams</a></div><div class="admin-card admin-form-card"><form method="post" action="<?= esc($formAction) ?>"><?php if ($error): ?><div class="admin-error"><?= esc($error) ?></div><?php endif; ?><label for="title">Assessment name</label><input id="title" name="title" placeholder="Associate Software Engineer Screening" value="<?= esc($data['title'] ?? '') ?>" required><label for="description">Description</label><textarea id="description" name="description" placeholder="Describe this assessment for administrators."><?= esc($data['description'] ?? '') ?></textarea><label for="start_at">Start time</label><input id="start_at" name="start_at" type="datetime-local" value="<?= esc($data['start_at'] ?? '') ?>"><label for="end_at">End time</label><input id="end_at" name="end_at" type="datetime-local" value="<?= esc($data['end_at'] ?? '') ?>"><label for="duration_minutes">Assessment duration in minutes</label><input id="duration_minutes" name="duration_minutes" type="number" min="1" value="<?= esc($data['duration_minutes'] ?? 45) ?>" required><label for="status">Exam status</label><select id="status" name="status"><option value="draft" <?= ($data['status'] ?? 'draft') === 'draft' ? 'selected' : '' ?>>Draft</option><option value="active" <?= ($data['status'] ?? '') === 'active' ? 'selected' : '' ?>>Active</option><option value="archived" <?= ($data['status'] ?? '') === 'archived' ? 'selected' : '' ?>>Archived</option></select><p style="font-size:13px;color:#798196">Only active exams within their schedule are shown to applicants.</p><label style="display:flex;align-items:center;gap:10px;font-weight:600"><input name="allow_multiple_submissions" type="checkbox" value="1" style="width:18px;height:18px" <?= !empty($data['allow_multiple_submissions']) ? 'checked' : '' ?>> Allow multiple submissions</label><p style="font-size:13px;color:#798196">When disabled, an applicant can submit this assessment only once.</p><button class="admin-btn" type="submit" style="margin-top:22px"><?= esc($submitLabel) ?></button></form></div></div></main></div></body></html>
